"use client";

import { useMemo, useRef, useState } from "react";

import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Map,
  MapControls,
  MapGeoJSON,
  MapPopup,
  type MapRef,
} from "@/components/ui/map";
import { MemberAvatar } from "./components/member-avatar";
import { MemberList } from "./components/member-list";
import { MemberMarker } from "./components/member-marker";
import {
  mapView,
  members,
  type Member,
  type MemberGroup,
  WORLD_GEOJSON,
} from "./data";

type Filter = "all" | "awake";

const awakeMembers = members.filter((member) => member.awake);

const GLOBE_PROJECTION = { type: "globe" };
const MARKER_SPACING_PX = 60;
const WORLD_SIZE_PX = 512;
const HIDE_COVERED_CLASS =
  "[&_.maplibregl-marker[style*='opacity:_0;']]:pointer-events-none [&_.maplibregl-popup[style*='opacity:_0;']_*]:pointer-events-none!";

export default function Page() {
  const mapRef = useRef<MapRef>(null);
  const [filter, setFilter] = useState<Filter>("all");
  const [zoom, setZoom] = useState(mapView.zoom);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const visibleMembers = filter === "awake" ? awakeMembers : members;

  const groups = useMemo(
    () => groupMembers(visibleMembers, zoom),
    [visibleMembers, zoom],
  );

  const selected = visibleMembers.find((member) => member.id === selectedId);
  if (selectedId && !selected) setSelectedId(null);

  const handleSelect = (member: Member) => {
    setSelectedId(member.id);
    mapRef.current?.flyTo({
      center: [member.lng, member.lat],
      zoom: mapView.maxZoom,
    });
  };

  return (
    <div className="bg-background flex h-dvh flex-col-reverse md:flex-row">
      <aside className="bg-sidebar text-sidebar-foreground flex h-1/2 shrink-0 flex-col md:h-auto md:w-72 md:border-r">
        <div className="p-3">
          <p className="text-foreground text-sm font-medium">Community</p>
          <p className="text-muted-foreground mt-0.5 text-xs tabular-nums">
            {members.length} members, {awakeMembers.length} awake
          </p>
          <Tabs
            value={filter}
            onValueChange={(value) => setFilter(value as Filter)}
            className="mt-3"
          >
            <TabsList className="w-full">
              <TabsTrigger value="all">All</TabsTrigger>
              <TabsTrigger value="awake">Awake</TabsTrigger>
            </TabsList>
          </Tabs>
        </div>
        <MemberList
          members={visibleMembers}
          selectedId={selected?.id}
          onSelect={handleSelect}
        />
      </aside>

      <div className="relative min-h-0 min-w-0 flex-1">
        <Map
          ref={mapRef}
          blank
          projection={GLOBE_PROJECTION}
          center={mapView.center}
          zoom={mapView.zoom}
          minZoom={mapView.minZoom}
          maxZoom={mapView.maxZoom}
          className={HIDE_COVERED_CLASS}
          onViewportChange={(viewport) =>
            setZoom(Math.round(viewport.zoom * 2) / 2)
          }
        >
          <MapGeoJSON data={WORLD_GEOJSON} linePaint={false} />

          {groups.map((group) => (
            <MemberMarker
              key={group.members[0].id}
              group={group}
              selectedId={selected?.id}
              onSelect={handleSelect}
            />
          ))}

          {selected && (
            <MapPopup
              key={selected.id}
              longitude={selected.lng}
              latitude={selected.lat}
              offset={20}
              closeButton
              closeOnClick={false}
              focusAfterOpen={false}
              locationOccludedOpacity={0}
              onClose={() => setSelectedId(null)}
              className="pr-8"
            >
              <div className="flex items-center gap-2.5">
                <MemberAvatar member={selected} />
                <div>
                  <p className="text-xs font-medium">{selected.name}</p>
                  <p className="text-muted-foreground text-[11px]">
                    {selected.city}
                  </p>
                </div>
              </div>
              <p className="text-muted-foreground mt-2 text-[11px] tabular-nums">
                {selected.localTime} local,{" "}
                {selected.awake ? "awake" : "asleep"}
              </p>
            </MapPopup>
          )}

          <MapControls />
        </Map>
      </div>
    </div>
  );
}

function groupMembers(items: Member[], zoom: number) {
  const spacing = (MARKER_SPACING_PX / (WORLD_SIZE_PX * 2 ** zoom)) * 360;
  const groups: MemberGroup[] = [];

  for (const member of items) {
    const group = groups.find(({ lng, lat }) => {
      const dx = (member.lng - lng) * Math.cos((lat * Math.PI) / 180);
      return Math.hypot(dx, member.lat - lat) < spacing;
    });

    if (!group) {
      groups.push({ lng: member.lng, lat: member.lat, members: [member] });
      continue;
    }

    const count = group.members.push(member);
    group.lng += (member.lng - group.lng) / count;
    group.lat += (member.lat - group.lat) / count;
  }

  return groups;
}

"use client";

import { Moon } from "lucide-react";

import {
  MapMarker,
  MarkerContent,
  MarkerTooltip,
  useMap,
} from "@/components/ui/map";
import { mapView, type Member, type MemberGroup } from "../data";
import { MemberAvatar } from "./member-avatar";

interface MemberMarkerProps {
  group: MemberGroup;
  selectedId?: string;
  onSelect: (member: Member) => void;
}

export function MemberMarker({
  group,
  selectedId,
  onSelect,
}: MemberMarkerProps) {
  const { map } = useMap();
  const [lead] = group.members;
  const count = group.members.length;

  const handleClick = () => {
    if (!map || count === 1 || map.getZoom() >= mapView.maxZoom) {
      onSelect(lead);
      return;
    }
    map.flyTo({
      center: [group.lng, group.lat],
      zoom: Math.min(map.getZoom() + 2, mapView.maxZoom),
    });
  };

  return (
    <MapMarker
      longitude={group.lng}
      latitude={group.lat}
      opacityWhenCovered={0}
      onClick={handleClick}
    >
      <MarkerContent>
        <div className="relative transition-transform hover:scale-110">
          <MemberAvatar
            member={lead}
            alt={lead.name}
            dimmed={!lead.awake}
            className="ring-background size-9 shadow-md ring-2"
          />
          {count > 1 ? (
            <span className="bg-foreground text-background ring-background absolute -top-1 -right-1 flex size-4.5 items-center justify-center rounded-full text-[10px] font-medium tabular-nums ring-2">
              {count}
            </span>
          ) : (
            !lead.awake && (
              <span className="bg-background text-muted-foreground absolute -top-1 -right-1 flex size-4.5 items-center justify-center rounded-full">
                <Moon className="size-2.5 fill-current" />
              </span>
            )
          )}
        </div>
      </MarkerContent>
      {(count > 1 || lead.id !== selectedId) && (
        <MarkerTooltip
          offset={26}
          className="bg-popover text-popover-foreground min-w-36 border p-2"
        >
          <div className="space-y-1.5">
            {group.members.map((member) => (
              <div key={member.id} className="text-[11px]">
                <div className="flex items-center justify-between gap-3">
                  <span className="font-medium">{member.name}</span>
                  {!member.awake && (
                    <Moon className="text-muted-foreground size-2.5" />
                  )}
                </div>
                <div className="text-muted-foreground mt-0.5 flex items-center justify-between gap-3">
                  <span>{member.city}</span>
                  <span className="tabular-nums">{member.localTime}</span>
                </div>
              </div>
            ))}
          </div>
        </MarkerTooltip>
      )}
    </MapMarker>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { Moon } from "lucide-react";

import type { Member } from "../data";
import { MemberAvatar } from "./member-avatar";

interface MemberListProps {
  members: Member[];
  selectedId?: string;
  onSelect: (member: Member) => void;
}

export function MemberList({ members, selectedId, onSelect }: MemberListProps) {
  const listRef = useRef<HTMLUListElement>(null);
  const selectedRef = useRef<HTMLButtonElement>(null);
  const memberCount = members.length;

  useEffect(() => {
    const list = listRef.current;
    const row = selectedRef.current;
    if (!list || !row) return;

    const listRect = list.getBoundingClientRect();
    const rowRect = row.getBoundingClientRect();
    if (rowRect.top < listRect.top) {
      list.scrollTop -= listRect.top - rowRect.top;
    } else if (rowRect.bottom > listRect.bottom) {
      list.scrollTop += rowRect.bottom - listRect.bottom;
    }
  }, [selectedId, memberCount]);

  return (
    <ul
      ref={listRef}
      className="flex flex-1 flex-col gap-1 overflow-y-auto p-2"
    >
      {members.map((member) => (
        <li key={member.id}>
          <button
            ref={member.id === selectedId ? selectedRef : undefined}
            type="button"
            onClick={() => onSelect(member)}
            aria-pressed={member.id === selectedId}
            className="hover:bg-muted aria-pressed:bg-muted flex w-full items-center gap-2.5 rounded-md px-2 py-1.5 text-left"
          >
            <MemberAvatar member={member} dimmed={!member.awake} />
            <div className="min-w-0 flex-1">
              <p className="text-foreground truncate text-xs font-medium">
                {member.name}
              </p>
              <p className="text-muted-foreground truncate text-[11px]">
                {member.city}
              </p>
            </div>
            <div className="text-muted-foreground flex shrink-0 items-center gap-1.5 text-[11px] tabular-nums">
              {!member.awake && <Moon className="size-2.5" />}
              {member.localTime}
            </div>
          </button>
        </li>
      ))}
    </ul>
  );
}

"use client";

import { useState } from "react";

import { cn } from "@/lib/utils";
import { getAvatarUrl, type Member } from "../data";

interface MemberAvatarProps {
  member: Member;
  alt?: string;
  dimmed?: boolean;
  className?: string;
}

export function MemberAvatar({
  member,
  alt = "",
  dimmed,
  className,
}: MemberAvatarProps) {
  const [failed, setFailed] = useState(false);

  return (
    <div
      className={cn(
        "bg-muted text-muted-foreground flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-full text-xs font-medium",
        dimmed && "opacity-70",
        className,
      )}
    >
      {failed ? (
        getInitials(member.name)
      ) : (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={getAvatarUrl(member.id)}
          alt={alt}
          draggable={false}
          onError={() => setFailed(true)}
          className="size-full object-cover"
        />
      )}
    </div>
  );
}

function getInitials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .slice(0, 2)
    .join("");
}
